import{_ as e,o as t,c as l,a2 as i}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"6.4 长期运行与 v1.0 验收","description":"长期稳定运行，完成整体验收后发布 v1.0。","frontmatter":{"title":"6.4 长期运行与 v1.0 验收","description":"长期稳定运行，完成整体验收后发布 v1.0。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-6/6-4.md","filePath":"delivery/stage-6/6-4.md","lastUpdated":1794017073000}'),r={name:"delivery/stage-6/6-4.md"};function o(s,a,n,d,h,c){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="_6-4-长期运行与-v1-0-验收" tabindex="-1">6.4 长期运行与 v1.0 验收 <a class="header-anchor" href="#_6-4-长期运行与-v1-0-验收" aria-label="Permalink to &quot;6.4 长期运行与 v1.0 验收&quot;">​</a></h1><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><ul><li><strong>已实现：</strong> 健康快照包含运行时长、内存、磁盘、schema、任务计数、调度器、审批、kill switch 和最近一次维护；每 6 小时自动维护；诊断导出不含路径、密钥或环境秘密；运维页展示健康、维护和备份边界。</li><li><strong>仍未完成：</strong> 没有数周连续运行测试、资源漂移数据、真实 v1.0 安装/升级/迁移/退出验收，也没有完整的全任务类型回归矩阵。</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>让 Hearth 可以长期安静运行，并在完成全部能力验收后发布 v1.0。长期运行不只是“不崩溃”，还要资源可控、状态不漂移、权限不扩大。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>增加健康检查、资源上限、日志和异常提醒，出现问题时用户能知道。</li><li>定期清理临时文件、过期任务和不再需要的缓存，避免长期占用资源。</li><li>做至少数周的连续运行测试，检查内存、任务状态、同步和权限是否稳定。</li><li>完成覆盖主要任务类型的整体验收，包括安装、升级、备份、恢复、撤销和隐私说明。</li><li>检查所有高风险动作仍然需要审批，所有外部操作都有回执。</li><li>只有当用户可以独立安装、长期使用、迁移和退出时，才发布 v1.0。</li></ol>',7)])])}const v=e(r,[["render",o]]);export{u as __pageData,v as default};
